@@ -1,3 +1,47 @@
+const UNIT_MS = {
+  d: 24 * 60 * 60 * 1000,
+  h: 60 * 60 * 1000,
+  m: 60 * 1000,
+  s: 1000,
+  ms: 1,
+};
+
+const COMPONENT_RE = /\s*(\d+)(ms|d|h|m|s)/g;
+
 export function parseDuration(value) {
-  return Number(value);
+  if (typeof value !== "string" || value.length === 0) {
+    throw new Error("Invalid duration: input must be a non-empty string");
+  }
+
+  const seenUnits = new Set();
+  let totalMs = 0;
+  let lastIndex = 0;
+
+  COMPONENT_RE.lastIndex = 0;
+  let match;
+  while ((match = COMPONENT_RE.exec(value)) !== null) {
+    if (match.index !== lastIndex) {
+      throw new Error(`Invalid duration: unexpected characters in "${value}"`);
+    }
+
+    const [full, amount, unit] = match;
+
+    if (seenUnits.has(unit)) {
+      throw new Error(`Invalid duration: duplicate unit "${unit}" in "${value}"`);
+    }
+    seenUnits.add(unit);
+
+    totalMs += Number(amount) * UNIT_MS[unit];
+    lastIndex += full.length;
+  }
+
+  if (lastIndex !== value.length) {
+    throw new Error(`Invalid duration: unexpected characters in "${value}"`);
+  }
+
+  if (seenUnits.size === 0) {
+    throw new Error(`Invalid duration: no valid components found in "${value}"`);
+  }
+
+  return totalMs;
 }
